package com.projecteden.profile.service; import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.projecteden.character.repository.CharacterRepository;import com.projecteden.common.exception.ResourceNotFoundException;import com.projecteden.profile.domain.Profile;import com.projecteden.profile.dto.*;import com.projecteden.profile.repository.ProfileRepository;import com.projecteden.user.domain.User;import com.projecteden.user.repository.UserRepository;import com.projecteden.world.repository.WorldRepository;
@Service public class ProfileService{private final ProfileRepository profiles;private final UserRepository users;private final CharacterRepository characters;private final WorldRepository worlds;public ProfileService(ProfileRepository profiles,UserRepository users,CharacterRepository characters,WorldRepository worlds){this.profiles=profiles;this.users=users;this.characters=characters;this.worlds=worlds;}@Transactional public ProfileResponseDTO get(Long id){User u=user(id);return response(profiles.findByUser(u).orElseGet(()->profiles.save(Profile.create(u))));}@Transactional public ProfileResponseDTO update(Long id,ProfileUpdateDTO d){User u=user(id);if(d.nickname()!=null&&!d.nickname().isBlank())u.updateNickname(d.nickname());Profile p=profiles.findByUser(u).orElseGet(()->profiles.save(Profile.create(u)));p.update(d.avatarUrl(),d.representativeCreature(),d.representativeIsland());return response(p);}private User user(Long id){return users.findById(id).orElseThrow(()->new ResourceNotFoundException("사용자를 찾을 수 없습니다."));}private ProfileResponseDTO response(Profile p){var c=characters.findByUserId(p.getUserId()).orElse(null);var w=c==null?null:worlds.findByCharacterId(c.getId()).orElse(null);return new ProfileResponseDTO(p.getUserId(),p.getUser().getNickname(),p.getAvatarUrl(),p.getJoinDate(),p.getTotalPlayDays(),w==null?p.getCurrentSeason():w.getSeason().name(),p.getRepresentativeCreature(),p.getRepresentativeIsland());}}
